module isochronous_spill_register #(
    parameter WIDTH = 8
)(
    input              src_clk_i,
    input              src_rst_ni,
    input              src_valid_i,
    output             src_ready_o,
    input  [WIDTH-1:0] src_data_i,
    input              dst_clk_i,
    input              dst_rst_ni,
    output             dst_valid_o,
    input              dst_ready_i,
    output reg [WIDTH-1:0] dst_data_o
);

    // Source domain state: 0 = empty, 1 = full
    reg src_state;
    // Destination domain state: 0 = empty, 1 = full
    reg dst_state;
    // Data storage for the buffer
    reg [WIDTH-1:0] buffer_data;

    // Synchronize src_valid to dst domain to detect when the buffer becomes empty
    reg src_valid_synced;
    reg src_valid_synced_2;

    // Synchronize dst_ready to src domain to detect when the buffer becomes full
    reg dst_ready_synced;
    reg dst_ready_synced_2;

    // ---------------------------------------------------------
    // Source Domain Logic
    // ---------------------------------------------------------
    always @(posedge src_clk_i or negedge src_rst_ni) begin
        if (!src_rst_ni) begin
            src_state <= 1'b0;
            src_valid_synced <= 1'b0;
            src_valid_synced_2 <= 1'b0;
            src_ready_o <= 1'b1;
        end else begin
            // Update synchronization signals
            src_valid_synced <= src_valid_i;
            src_valid_synced_2 <= src_valid_synced;

            // Determine if buffer is empty based on destination domain feedback
            // We need to know if dst_state is 0. Since dst_state is in dst domain,
            // we must synchronize it to src domain.
            // However, a simpler approach for 2-deep buffer with related clocks:
            // We track the count of items in the buffer.
            // Let's refine the state machine to be robust.

            // Re-evaluating state logic for clarity and correctness:
            // State 0: Buffer Empty
            // State 1: Buffer Full (1 item)
            // State 2: Buffer Full (2 items) - Max depth

            // We need to know dst_state in src domain.
            // Let's add a counter or state machine in src domain that tracks
            // the number of items currently in the buffer by observing dst_valid/dst_ready.
            // Actually, the standard way is to have the src domain drive the buffer
            // and the dst domain drive the consumption, with cross-domain handshaking.

            // Let's use a simple counter approach synchronized across domains.
            // But since we are restricted to one module and standard practices:
            // We will implement the state machine in both domains independently
            // and use the cross-domain signals to update the state.

            // To avoid race conditions, we assume the clocks are related (integer ratio).
            // We will use a 2-bit counter in src domain to track buffer occupancy.
            // But wait, the occupancy is determined by the interaction of src_valid
            // and dst_ready.

            // Correct approach for 2-deep buffer:
            // Src Domain:
            //   - If state < 2 and src_valid && src_ready (which is !full), accept data.
            //   - src_ready = (state < 2) ? 1 : 0.
            //   - On accept, state++.
            //   - We need to know if dst has consumed the item.
            //   - We can't know dst consumption directly in src without a signal.
            //   - Signal: dst_valid_synced tells us dst has an item ready to send.
            //   - Signal: dst_ready_synced tells us dst is ready to accept.
            //   - Actually, the standard "Spill Buffer" pattern:
            //     Src Domain tracks how many items are waiting to be sent to Dst.
            //     Dst Domain tracks how many items are waiting to be sent to Src (none, usually).
            //     Wait, the buffer holds data.
            //     Src pushes -> Buffer.
            //     Dst pulls -> Buffer.
            //     Src needs to know if Buffer is full (2 items).
            //     Dst needs to know if Buffer is empty (0 items).

            // Let's implement a counter in Src domain that increments on push and decrements on pull.
            // Push condition: src_valid && (counter < 2).
            // Pull condition: (counter > 0) && dst_ready.
            // But we need to know when dst_ready is true in Src domain.
            // And we need to know when dst_valid is true in Dst domain (to know if we can pull? No, dst pulls automatically if ready).

            // Refined Logic:
            // Src Domain Counter (count_src): Number of items in buffer.
            //   - Increment when src_valid && count_src < 2.
            //   - Decrement when dst_ready is detected in Src domain AND count_src > 0.
            // Dst Domain Counter (count_dst): Number of items in buffer.
            //   - This is redundant if we trust the cross-domain sync, but let's stick to one source of truth per domain.
            //   - Actually, the state must be consistent.
            //   - Let's use a single 2-bit counter in Src domain and a single 2-bit counter in Dst domain.
            //   - They should be equal at stable times, but might differ during transitions.
            //   - To be safe, we implement the logic in both domains.

            // Src Domain Logic:
            //   - count_src: 0, 1, 2.
            //   - src_ready_o = (count_src < 2).
            //   - If src_valid_i && src_ready_o: count_src <= count_src + 1.
            //   - If dst_ready_synced && count_src > 0: count_src <= count_src - 1.

            // Dst Domain Logic:
            //   - count_dst: 0, 1, 2.
            //   - dst_valid_o = (count_dst > 0).
            //   - If dst_valid_o && dst_ready_i: count_dst <= count_dst - 1.
            //   - If src_valid_synced && count_dst < 2: count_dst <= count_dst + 1.

            // This creates a potential race if not careful, but with related clocks and proper synchronization, it works.
            // We need to ensure the counters don't diverge.
            // The divergence happens only during the clock cycle where both domains see a change.
            // Since we use 2-deep, we have enough slack.

            // Let's implement the Src Domain Counter logic here.
            // We need to synchronize dst_ready to Src domain.
            // We already have dst_ready_synced and dst_ready_synced_2.
            // We use the delayed version to avoid metastability on the same cycle.

            if (src_valid_i && (count_src < 2)) begin
                count_src <= count_src + 1;
            end else if (dst_ready_synced_2 && (count_src > 0)) begin
                count_src <= count_src - 1;
            end else begin
                // Hold
            end

            // Output ready
