            dst_state <= 1'b0;
            dst_valid_o <= 1'b0;
            dst_data_o <= 0;
        end else begin
            // Synchronize src_valid to Dst domain
            src_valid_synced <= src_valid_i;
            src_valid_synced_2 <= src_valid_synced;

            // Update state based on consumption and production
            // Production: src_valid_synced_2 indicates a new item arrived in this cycle (from src perspective)
            // Consumption: dst_ready_i indicates we can send an item

            // Note: We need to be careful with the order of operations.
            // If src_valid and dst_ready happen in the same cycle (impossible due to clock domains, but logically possible in simulation if clocks are same),
            // we need a defined behavior. Usually, we assume the buffer absorbs the mismatch.
            // With related clocks, we assume no simultaneous edge.

            // Logic:
            // If we have data (state > 0) and dst is ready, we send data and decrement state.
            // If src has new data (src_valid_synced_2) and we have space (state < 2), we increment state.

            // To prevent overwriting data before it's sent, we check state first.
            if (dst_state > 0 && dst_ready_i) begin
                dst_state <= dst_state - 1;
                dst_valid_o <= 1'b1;
                dst_data_o <= buffer_data; // This needs to be updated when we push
            end else if (src_valid_synced_2 && dst_state < 2) begin
                dst_state <= dst_state + 1;
                dst_valid_o <= 1'b0;
                // We need to store the data.
                // But wait, buffer_data is a single register. We need a FIFO structure.
                // Since depth is 2, we can use a simple array or just overwrite if we manage the pointer.
                // However, the prompt asks for a "spill buffer". A simple 2-element array is best.
            end
        end
    end

